#!/usr/bin/env python3
"""PreToolUse guard for the {{SLUG}} runner and verifier. Stdlib only. Generated by harness-builder {{VERSION}}.

A tripwire, not a sandbox. It narrows what a confused or hijacked run can do, on top of Claude Code's
permission rules and (recommended) /sandbox. The runner and verifier register it through guard.sh,
which blocks the call if Python is missing or this script fails.

During a run:
- Bash: only `python <harness>/scripts/ingest.py|check_run.py|render_report.py ...`, with a bare
  interpreter name (no ./python or runs/python) and no shell operators (no `python -c`, pipes,
  redirects, chaining or substitution). An allowed ingest.py call also refreshes memory/.guard-ok,
  the stamp ingest.py checks to prove the guard is running.
- Edit / Write / NotebookEdit / MultiEdit: only inside <harness>/runs/.
- Read / Grep / Glob: only inside <harness>/, with an explicit path.
- Agent (Task): only the {{SLUG}}-verifier subagent.
- Any other tool: blocked, unless its exact name is in EXTRA_TOOLS.
Writes "allow" to stdout and exits 0 to allow. Writes the reason to stderr and exits 2 to block,
including when anything goes wrong.
"""
import json
import os
import re
import shlex
import sys
import time
from pathlib import Path

HARNESS = "{{HARNESS_DIR}}"
SLUG = "{{SLUG}}"
SCRIPTS = ("ingest.py", "check_run.py", "render_report.py")
FORBIDDEN = set(";&|`$<>(){}\n\r")
PYTHONS = {"python", "python3", "py", "python.exe", "python3.exe", "py.exe"}
READ_TOOLS = {"Read", "Grep", "Glob"}
WRITE_TOOLS = {"Edit", "Write", "NotebookEdit", "MultiEdit"}
# Exact names of extra tools a run truly needs (read-only ones only). Each one widens the run.
EXTRA_TOOLS = set()


class Blocked(Exception):
    pass


def inside(path, root):
    return path == root or root in path.parents


def resolve(project, target, what):
    if not isinstance(target, str) or not target.strip():
        raise Blocked(f"{what} needs an explicit path inside {HARNESS}/")
    p = Path(target)
    return (p if p.is_absolute() else project / p).resolve()


def check_bash(cmd, project, harness):
    rule = (f"during a run only `python {HARNESS}/scripts/ingest.py|check_run.py|render_report.py <args>` "
            f"may run, with a bare interpreter name and no shell operators")
    if not isinstance(cmd, str) or not cmd.strip() or FORBIDDEN & set(cmd):
        raise Blocked(f"{rule}; got: {str(cmd)[:120]}")
    tokens = [t.strip("\"'") for t in shlex.split(cmd, posix=False)]
    if not tokens or tokens[0].lower() not in PYTHONS:
        raise Blocked(f"{rule}; got: {cmd[:120]}")
    rest = tokens[1:]
    if rest[:1] == ["-3"]:
        rest = rest[1:]
    if not rest or rest[0].startswith("-"):
        raise Blocked(f"{rule}; got: {cmd[:120]}")
    script = resolve(project, rest[0], "Bash")
    if script not in {(harness / "scripts" / s).resolve() for s in SCRIPTS}:
        raise Blocked(f"{rule}; got: {cmd[:120]}")
    if "--unguarded" in rest:
        raise Blocked("--unguarded is only for runs outside Claude Code")
    if script.name == "ingest.py":
        stamp = harness / "memory" / ".guard-ok"   # outside runs/, so the run itself cannot write it
        stamp.parent.mkdir(parents=True, exist_ok=True)
        stamp.write_text(str(time.time()), encoding="utf-8")


def check_pattern(pattern):
    if isinstance(pattern, str) and (".." in pattern or pattern.startswith(("/", "\\", "~"))
                                     or re.match(r"^[A-Za-z]:", pattern)):
        raise Blocked(f"during a run, search patterns stay inside {HARNESS}/; got: {pattern}")


def search_base(project, data, tool):
    """Where a Grep or Glob really searches: its path plus the literal start of its pattern."""
    pattern = data.get("pattern") if tool == "Glob" else data.get("glob")
    check_pattern(pattern)
    base = resolve(project, data.get("path") or str(project), tool)
    literal = []
    for part in re.split(r"[\\/]+", pattern) if isinstance(pattern, str) else []:
        if not part or any(c in part for c in "*?[{"):
            break
        literal.append(part)
    return (base.joinpath(*literal)).resolve() if literal else base


def decide(event):
    if not isinstance(event, dict):
        raise Blocked("could not read the tool call")
    tool, data = event.get("tool_name"), event.get("tool_input")
    if not isinstance(tool, str) or not isinstance(data, dict):
        raise Blocked("could not read the tool call")
    project = Path(os.environ.get("CLAUDE_PROJECT_DIR") or event.get("cwd") or ".").resolve()
    harness = (project / HARNESS).resolve()
    if tool == "Bash":
        check_bash(data.get("command"), project, harness)
    elif tool in WRITE_TOOLS:
        target = data.get("file_path") or data.get("notebook_path")
        if not inside(resolve(project, target, tool), harness / "runs"):
            raise Blocked(f"during a run, writes are limited to {HARNESS}/runs/; got: {target}")
    elif tool == "Read":
        target = data.get("file_path")
        if not inside(resolve(project, target, tool), harness):
            raise Blocked(f"during a run, Read is limited to {HARNESS}/; got: {target}")
    elif tool in READ_TOOLS:
        base = search_base(project, data, tool)
        if not inside(base, harness):
            raise Blocked(f"during a run, {tool} is limited to {HARNESS}/ (set path or a pattern starting "
                          f"with {HARNESS}/); got: {data.get('path') or '.'}")
    elif tool in {"Agent", "Task"}:
        if data.get("subagent_type") != f"{SLUG}-verifier":
            raise Blocked(f"during a run, only the {SLUG}-verifier subagent may start; got: {data.get('subagent_type')}")
    elif tool not in EXTRA_TOOLS:
        raise Blocked(f"during a run, the {tool} tool is not allowed")


def main():
    try:
        raw = sys.stdin.buffer.read().decode("utf-8", "replace")
        decide(json.loads(raw) if raw.strip() else None)
    except Blocked as exc:
        sys.stderr.write(f"harness guard: {exc}\n")
        sys.exit(2)
    except Exception as exc:  # noqa: BLE001 - fail closed on anything unexpected
        sys.stderr.write(f"harness guard: blocked because the guard could not decide ({type(exc).__name__}: {exc})\n")
        sys.exit(2)
    sys.stdout.write("allow")
    sys.exit(0)


if __name__ == "__main__":
    main()
